<script setup lang="ts">
import {ref,onMounted,onUnmounted,watch} from 'vue'
import {useRoute,useRouter} from 'vue-router'
import {useAuth} from '../../entities/auth/model'
import {request,query,errorMessage,isCancelled} from '../../shared/api/client'
import type {CallList,Taxonomy,Filter,SavedFilter} from '../../shared/interfaces'
import {emptyFilter,validateFilter} from '../../shared/lib/filter'
import {resultLabels} from '../../shared/lib/format'
import {recordingLabels} from '../../shared/lib/recording-state'
import CallTable from '../../features/call-table/CallTable.vue'
import CallFilters from '../../features/filter-builder/CallFilters.vue'
import CallActionSidebar from '../../features/call-actions/CallActionSidebar.vue'
import FilterBuilder from '../../features/filter-builder/FilterBuilder.vue'
import Icon from '../../shared/ui/Icon.vue'
import Empty from '../../shared/ui/Empty.vue'
import Notice from '../../shared/ui/Notice.vue'
const auth=useAuth(),route=useRoute(),router=useRouter()
const data=ref<CallList|null>(null),taxonomy=ref<Taxonomy>({tags:[],statuses:[]}),saved=ref<SavedFilter[]>([]),loading=ref(true),error=ref(''),success=ref(''),search=ref(String(route.query.search||'')),from=ref(String(route.query.from||'')),to=ref(String(route.query.to||'')),result=ref(''),direction=ref(''),recording=ref(''),showBuilder=ref(false),ast=ref<Filter>(emptyFilter()),filterName=ref(''),selected=ref<string[]>([]),cursor=ref<string|null>(null),pageNumber=ref(1),workspaceFilter=ref<Filter>(emptyFilter()),filterReset=ref(0),actionCall=ref('')
let timer:ReturnType<typeof setInterval>|undefined
try{if(route.query.filter){ast.value=validateFilter(JSON.parse(String(route.query.filter)));showBuilder.value=true}}catch{}
function combined(){const rules:Filter[]=[];if(direction.value)rules.push({field:'direction',op:'eq',value:direction.value});if(result.value)rules.push({field:'provider_result',op:'eq',value:result.value});if(recording.value)rules.push({field:'recording_state',op:'eq',value:recording.value});if(showBuilder.value)rules.push(validateFilter(ast.value));const extra=validateFilter(workspaceFilter.value);if(!('rules'in extra)||extra.rules.length)rules.push(extra);return{op:'and' as const,rules}}
async function load(reset=false,background=false){if(reset){cursor.value=null;pageNumber.value=1;selected.value=[]}if(!background)loading.value=true;error.value='';try{const filter=combined();data.value=await request<CallList>('/calls'+query({search:search.value,from:from.value,to:to.value,filter,cursor:cursor.value,limit:25}));await router.replace({path:'/calls',query:{...(search.value?{search:search.value}:{}),...(from.value?{from:from.value}:{}),...(to.value?{to:to.value}:{}),...(filter.rules.length?{filter:JSON.stringify(filter)}:{})}})}catch(e){if(!isCancelled(e))error.value=errorMessage(e)}finally{loading.value=false}}
async function next(){if(!data.value?.next_cursor)return;cursor.value=data.value.next_cursor;pageNumber.value++;await load()}
async function save(){try{error.value='';if(!filterName.value.trim())throw Error('Введите название представления');await request('/filters',{method:'POST',body:{name:filterName.value,ast:combined()}});saved.value=(await request<{items:SavedFilter[]}>('/filters')).items;success.value='Представление сохранено';filterName.value=''}catch(e){error.value=errorMessage(e)}}
function applySaved(event:Event){const value=(event.target as HTMLSelectElement).value;const item=saved.value.find(f=>f.id===value);if(item){ast.value=item.ast;showBuilder.value=true;direction.value='';result.value='';recording.value='';filterReset.value++;workspaceFilter.value=emptyFilter();load(true)}}
async function removeSaved(id:string){try{await request('/filters/'+id,{method:'DELETE'});saved.value=saved.value.filter(f=>f.id!==id)}catch(e){error.value=errorMessage(e)}}
async function exportSelected(provider:string){if(!selected.value.length)return;try{await request('/integrations/export',{method:'POST',body:{call_ids:selected.value,provider}});success.value='Экспорт поставлен в очередь. Состояние доступно в интеграциях.'}catch(e){error.value=errorMessage(e)}}
onMounted(async()=>{await Promise.allSettled([load(),request<Taxonomy>('/taxonomy').then(v=>taxonomy.value=v),request<{items:SavedFilter[]}>('/filters').then(v=>saved.value=v.items)]);timer=setInterval(()=>{if(!document.hidden&&!selected.value.length)load(false,true)},30000)})
onUnmounted(()=>clearInterval(timer))
watch(showBuilder,()=>{if(!showBuilder.value)ast.value=emptyFilter()})
</script>
<template><div class="page-heading"><div><span class="eyebrow">Единая история обращений</span><h1>Все звонки <span class="view-count">{{data?.total??'—'}}</span></h1><p>Найдите нужный разговор, проверьте качество и продолжите работу с клиентом.</p></div><div class="heading-actions"><button class="button" @click="load(false)"><Icon name="refresh" :size="15"/>Обновить</button><RouterLink v-if="auth.isOwner" class="button primary" to="/settings/telphin"><Icon name="link" :size="15"/>Подключение Телфина</RouterLink></div></div><Notice :message="error" kind="error"/><Notice :message="success" kind="success"/>
<div class="card" style="padding:18px 20px;margin-bottom:20px"><form class="toolbar" style="margin-bottom:0" @submit.prevent="load(true)"><div class="search-input"><Icon name="search" :size="17"/><input v-model="search" aria-label="Поиск звонков" placeholder="Номер, клиент или сотрудник"/></div><input v-model="from" type="date" aria-label="С даты"/><input v-model="to" type="date" aria-label="По дату"/><select v-model="direction" aria-label="Направление"><option value="">Все направления</option><option value="in">Входящие</option><option value="out">Исходящие</option><option value="internal">Внутренние</option></select><select v-model="result" aria-label="Результат"><option value="">Все результаты</option><option v-for="(label,value) in resultLabels" :key="value" :value="value">{{label}}</option></select><select v-model="recording" aria-label="Запись"><option value="">Все записи</option><option v-for="(label,value) in recordingLabels" :key="value" :value="value">{{label}}</option></select><button class="button primary" type="submit">Найти</button><button class="button" type="button" @click="showBuilder=!showBuilder"><Icon name="filter" :size="14"/>Конструктор</button></form>
<CallFilters v-model="workspaceFilter" :taxonomy="taxonomy" :reset-key="filterReset"/><div class="form-actions"><button class="button primary small" @click="load(true)">Применить фильтры</button></div><div v-if="saved.length" class="row-actions" style="margin-top:13px"><select aria-label="Сохранённые представления" value="" @change="applySaved"><option value="">Сохранённые представления</option><option v-for="f in saved" :key="f.id" :value="f.id">{{f.name}}</option></select><span v-for="f in saved.slice(0,3)" :key="f.id" class="badge outline">{{f.name}}<button v-if="auth.canWrite" aria-label="Удалить представление" @click="removeSaved(f.id)">×</button></span></div><div v-if="showBuilder" class="filter-builder"><FilterBuilder v-model="ast" :taxonomy="taxonomy"/><div class="form-actions"><input v-if="auth.canWrite" v-model="filterName" aria-label="Название представления" placeholder="Название представления"/><button v-if="auth.canWrite" class="button small" @click="save">Сохранить</button><button class="button primary small" @click="load(true)">Применить условия</button></div></div></div>
<Notice v-if="data&&!data.coverage.complete" :message="data.coverage.reason||'История загружена не полностью. Выводы о первичности и перезвонах могут быть ограничены.'"/>
<div v-if="selected.length&&auth.canWrite" class="notice info" style="display:flex;align-items:center;gap:12px;flex-wrap:wrap">Выбрано звонков: {{selected.length}}<button class="button small" @click="exportSelected('amocrm')">Отправить в amoCRM</button><button class="button small" @click="exportSelected('sheets')">В Google Таблицы</button><button class="text-link" @click="selected=[]">Снять выбор</button></div>
<div class="card"><Empty v-if="loading&&!data" loading/><template v-else-if="data?.items.length"><CallTable :calls="data.items" :taxonomy="taxonomy" :timezone="auth.me?.organization.timezone" v-model:selected="selected" :selectable="auth.canWrite" @manage="actionCall=$event"/><div class="table-footer"><span>Страница {{pageNumber}} · найдено {{data.total}} · {{auth.me?.organization.timezone}}</span><div class="row-actions"><button v-if="pageNumber>1" class="button small" @click="load(true)">К началу</button><button class="button small" :disabled="!data.next_cursor||loading" @click="next">Следующие <Icon name="chevron" :size="13"/></button></div></div></template><Empty v-else :title="error?'Не удалось загрузить звонки':'Звонки не найдены'" :description="error?'Проверьте соединение и повторите запрос.':'Попробуйте изменить фильтр или подключите Телфин, чтобы загрузить историю.'"><button class="button small" @click="load(true)">Повторить загрузку</button></Empty></div>
<CallActionSidebar v-if="actionCall" :key="actionCall" :call-id="actionCall" @close="actionCall=''" @saved="load(false,true)"/>
</template>
